SELECT full_name, pay
FROM staff
WHERE pay BETWEEN 20000 AND 45000;

SELECT s.full_name, o.title
FROM staff s
LEFT JOIN outlet o ON s.outlet_no = o.outlet_no;

SELECT e.full_name AS Staff_Name, e.reports_to AS Boss_Name
FROM staff AS e
LEFT JOIN staff AS s ON e.reports_to = s.staff_no;

SELECT pay_mode, COUNT(*) AS Bill_Count
FROM bill
GROUP BY pay_mode;

UPDATE staff
SET pay = pay * 1.12
WHERE duty = 'Waiter';

UPDATE bill
SET tip = 0
WHERE tip IS NULL;
